parts.openscad_module:
 = 128;

// ── Parameters ───────────────────────────────────────────
shaft_a     = 5;     // bore A (e.g. NEMA17 motor shaft)
shaft_b     = 8;     // bore B (e.g. T8 lead screw)
length      = 40;    // coupling body length
turns       = 2;     // helical turns over length
starts      = 2;     // helical starts (= number of beams)
beam_wall   = 3.5;   // radial wall of each beam
slot_w      = 1.5;   // helical slot width
running_fit = 0.25;  // bore clearance

// ── Derived ──────────────────────────────────────────────
bore_a     = shaft_a + 2 * running_fit;         // 5.5 mm
bore_b     = shaft_b + 2 * running_fit;         // 8.5 mm
bore_max   = max(bore_a, bore_b);
outer_d    = bore_max + 2 * beam_wall + 2;      // outer diameter
wall_depth = (outer_d - bore_max) / 2;          // radial wall depth
slot_r     = bore_max/2 + wall_depth/2;         // radial centre of helical slot

module helical_beam_coupler() {
    difference() {
        // ── Outer body — positive volume ──────────────────
        cylinder(d = outer_d, h = length, center = true);

        // ── Bore A from bottom end ─────────────────────────
        translate([0, 0, -(length/2) - 1])
            cylinder(d = bore_a, h = length/2 + 2);

        // ── Bore B from top end ────────────────────────────
        translate([0, 0, 0])
            cylinder(d = bore_b, h = length/2 + 2, center = false);

        // ── Helical slot cuts ─────────────────────────────
        // CORRECT: linear_extrude + twist creates true helical cuts.
        // WRONG:   rotate_extrude — creates a torus, not a helix.
        for (i = [0 : starts - 1])
            rotate([0, 0, i * 360 / starts])
            linear_extrude(height = length + 2,
                           twist  = -(360 * turns),
                           slices = 300,
                           center = true)
                translate([slot_r, 0])
                    square([wall_depth + 2, slot_w], center = true);

        // ── Set screw holes — radial, one per end boss ────
        for (end_z = [-(length/2 - 5), length/2 - 5])
            translate([0, outer_d/2, end_z])
                rotate([90, 0, 0])
                    cylinder(d = 3.4, h = outer_d/2 + 2);
    }
}

helical_beam_coupler();

$fn = 96;

// Parameters
shaft_a_d = 5;          // shaft A diameter
shaft_b_d = 8;          // shaft B diameter
coupler_len = 50;       // overall length
outer_d = 30;           // outer diameter
split_gap = 1.5;        // clamp slit width
running_fit = 0.25;     // bore running clearance
thread_clear = 0.4;     // clearance added to screw diameter
clamp_screw_d = 5 + thread_clear;
clamp_hole_offset = 8;  // distance from each end to screw centre
chamfer_h = 0.4;        // bottom chamfer height

// Derived
bore_a_d = shaft_a_d + running_fit;
bore_b_d = shaft_b_d + running_fit;
half_len = coupler_len / 2;

module split_clamp_coupler() {
    difference() {
        // Positive body volume.
        cylinder(d = outer_d, h = coupler_len, center = true);

        // Bore A enters from the bottom and reaches just past centre.
        translate([0, 0, -half_len - 0.5])
            cylinder(d = bore_a_d, h = half_len + 1, center = false);

        // Bore B enters from the top and reaches just past centre.
        translate([0, 0, -0.5])
            cylinder(d = bore_b_d, h = half_len + 1, center = false);

        // Radial clamp slit: thin in X, opens from the outside to the bore.
        translate([0, outer_d / 4, 0])
            cube([split_gap, outer_d / 2 + 2, coupler_len + 2], center = true);

        // Clamping screw holes cross the slit through solid wall material.
        for (z = [-half_len + clamp_hole_offset, half_len - clamp_hole_offset])
            translate([outer_d / 4, 0, z])
                rotate([90, 0, 0])
                    cylinder(d = clamp_screw_d, h = outer_d + 2, center = true);

        // Bottom edge chamfer, subtracted from the body.
        translate([0, 0, -half_len - 0.01])
            cylinder(d1 = outer_d + 2 * chamfer_h,
                     d2 = outer_d - 0.01,
                     h = chamfer_h,
                     center = false);
    }
}

split_clamp_coupler();
